mapper.select:
SELECT A.FINPROD_ID id, A.FINPROD_MARKET_ID text, A.FINPROD_NAME, TO_CHAR(A.VDATE, 'yyyy-MM-dd') VDATE, TO_CHAR(A.MDATE, 'yyyy-MM-dd') MDATE, TO_CHAR(A.IDATE, 'yyyy-MM-dd') IDATE, A.TRADE_MARKET, A.CCY, A.CALENDAR_ID, basisData.BASIS, B.TYPE_4 windtypeone, A.FINPROD_MARKET_ID, A.IS_RIGHT, A.REGIST_ORG FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_TYPE B ON B.FINPROD_ID = A.FINPROD_ID LEFT JOIN ( select max(BASIS) as BASIS, FINPROD_ID from FIN_CASH_CALC_RULE
AND FINPROD_ID = #{initValue}
group by FINPROD_ID ) basisData on A.FINPROD_ID = basisData.FINPROD_ID
( A.FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.FINPROD_ID = #{initValue}
AND A.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
AND B.TYPE_4 in
#{item}

SELECT fp.FINPROD_MARKET_ID bondCode, fp.FINPROD_ABBR bondAbbrName, fp.FINPROD_ID finprodId, fp.MDATE mdate, ava.AMOUNT * 100 prin, NVL(pledge.AMOUNT, 0) * 100 pledgePrin, NVL(pledge.AMOUNT, 0) * 100 pledgePrinInit, (NVL(ava.AMOUNT, 0) - NVL(pledge.AMOUNT, 0)) * 100 avaPledgePrin, mbvi.NETPRICE firstNetPrice, fp.REGIST_ORG repRegistOrg
, CASE WHEN ava.INV_AIM = #{INV_AIM_AC} THEN 1 WHEN ava.INV_AIM = #{INV_AIM_FVOCI} THEN 2 WHEN ava.INV_AIM = #{INV_AIM_FVTPL} THEN 3 ELSE 0 END invAimSort, ava.INV_AIM invAim
FROM ( SELECT FINPROD_ID,
INV_AIM,
SUM(NVL(AMOUNT, 0)) AMOUNT FROM PTL_SEC_POSITION WHERE PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR} AND TO_CHAR(CDATE, 'yyyy-MM-dd') = #{plateDate, jdbcType=VARCHAR} AND HODING_TYPE IN (#{POSITION_TYPE_01}, #{POSITION_TYPE_03})
AND SEC_ACCT_ID = #{secAcctId, jdbcType=VARCHAR}
AND SEC_ACCT_ID = #{chlId, jdbcType=VARCHAR}
AND FINPROD_ID = #{finprodId, jdbcType=VARCHAR}
GROUP BY FINPROD_ID
,INV_AIM
) ava LEFT JOIN ( SELECT FINPROD_ID,
INV_AIM,
SUM(NVL(AMOUNT, 0)) AMOUNT FROM PTL_SEC_POSITION WHERE PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR} AND TO_CHAR(CDATE, 'yyyy-MM-dd') = #{plateDate, jdbcType=VARCHAR} AND HODING_TYPE IN (#{POSITION_TYPE_04}, #{POSITION_TYPE_06}) GROUP BY FINPROD_ID
,INV_AIM
) pledge ON pledge.FINPROD_ID = ava.FINPROD_ID
AND pledge.INV_AIM = ava.INV_AIM
INNER JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = ava.FINPROD_ID
AND fp.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
LEFT JOIN MST_BOND_VALUATION_INFO mbvi ON mbvi.SEC_ID = fp.FINPROD_MARKET_ID AND TO_CHAR(mbvi.VALUE_DATE, 'yyyy-MM-dd') <= #{plateDate, jdbcType=VARCHAR} AND NOT EXISTS ( SELECT 1 FROM MST_BOND_VALUATION_INFO mbviInner WHERE mbviInner.SEC_ID = fp.FINPROD_MARKET_ID AND TO_CHAR(mbviInner.VALUE_DATE, 'yyyy-MM-dd') <= #{plateDate, jdbcType=VARCHAR} AND TO_CHAR(mbviInner.VALUE_DATE, 'yyyy-MM-dd') > TO_CHAR(mbvi.VALUE_DATE, 'yyyy-MM-dd') ) LEFT JOIN FIN_PRODUCT_TYPE FPT ON fp.FINPROD_ID = FPT.FINPROD_ID
AND fp.REGIST_ORG in
#{item}
AND fp.FINPROD_MARKET_ID = #{bondCode, jdbcType=VARCHAR}
AND FPT.TYPE_4 in
#{item, jdbcType=VARCHAR}
ORDER BY CASE WHEN ava.INV_AIM = #{INV_AIM_AC} THEN 1 WHEN ava.INV_AIM = #{INV_AIM_FVOCI} THEN 2 WHEN ava.INV_AIM = #{INV_AIM_FVTPL} THEN 3 END

SELECT fp.FINPROD_MARKET_ID bondCode, fp.FINPROD_ABBR bondAbbrName, fp.FINPROD_ID finprodId, fp.MDATE mdate, mbvi.NETPRICE firstNetPrice, fp.REGIST_ORG repRegistOrg FROM FIN_PRODUCT fp LEFT JOIN MST_BOND_VALUATION_INFO mbvi ON mbvi.SEC_ID = fp.FINPROD_MARKET_ID AND TO_CHAR(mbvi.VALUE_DATE, 'yyyy-MM-dd') <= #{plateDate, jdbcType=VARCHAR} AND NOT EXISTS ( SELECT 1 FROM MST_BOND_VALUATION_INFO mbviInner WHERE mbviInner.SEC_ID = fp.FINPROD_MARKET_ID AND TO_CHAR(mbviInner.VALUE_DATE, 'yyyy-MM-dd') <= #{plateDate, jdbcType=VARCHAR} AND TO_CHAR(mbviInner.VALUE_DATE, 'yyyy-MM-dd') > TO_CHAR(mbvi.VALUE_DATE, 'yyyy-MM-dd') ) LEFT JOIN FIN_PRODUCT_TYPE FPT ON fp.FINPROD_ID = FPT.FINPROD_ID
fp.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
AND fp.FINPROD_MARKET_ID = #{bondCode, jdbcType=VARCHAR}
AND fp.REGIST_ORG in
#{item}
AND FPT.TYPE_4 in
#{item, jdbcType=VARCHAR}

SELECT fp.FINPROD_MARKET_ID bondCode, fp.FINPROD_ABBR bondAbbrName, fp.MDATE mdate, (NVL(ava.AMOUNT, 0) - NVL(pledge.AMOUNT, 0)) * 100 avaPledgePrin, NVL(pledgeList.PLEDGE_NUMBER, 0) * 100 pledgePrin, mbvi.NETPRICE firstNetPrice, pledgeList.PLEDGE_RATIO*100 pledgeRatio, ava.AMOUNT * 100 prin, fp.REGIST_ORG repRegistOrg FROM (
SELECT ENTRUST_ID bussId, FINPROD_ID pledgeId, PLEDGE_FACE_VALUE, PLEDGE_NUMBER, PLEDGE_RATIO, PLEDGE_AMT FROM ETR_PLEDGE WHERE ENTRUST_ID = #{entrustId}
SELECT fdp.FINPROD_ID bussId, fdp.PLEDGE_FINPROD_ID pledgeId, fdp.PLEDGE_FACE_VALUE, fdp.PLEDGE_NUMBER, fdp.PLEDGE_RATIO, fdp.PLEDGE_AMT FROM FIN_DEAL_PLEDGE fdp LEFT JOIN TRD_PRODUCT_DEAL tpd ON tpd.TRADE_ID = fdp.FINPROD_ID WHERE (tpd.IS_CANCEL = #{YES_OR_NO_N} AND fdp.FINPROD_ID = #{bizCode}) OR (tpd.IS_CANCEL = #{YES_OR_NO_Y} AND fdp.FINPROD_ID = SUBSTR(#{bizCode}, 0, LENGTH(#{bizCode})-1))
) pledgeList LEFT JOIN ( SELECT FINPROD_ID, SUM(NVL(AMOUNT, 0)) AMOUNT FROM PTL_SEC_POSITION WHERE PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR} AND TO_CHAR(CDATE, 'yyyy-MM-dd') = #{plateDate, jdbcType=VARCHAR} AND HODING_TYPE IN (#{POSITION_TYPE_01}, #{POSITION_TYPE_03}) GROUP BY FINPROD_ID ) ava ON ava.FINPROD_ID = pledgeList.pledgeId LEFT JOIN ( SELECT FINPROD_ID, SUM(NVL(AMOUNT, 0)) AMOUNT FROM PTL_SEC_POSITION WHERE PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR} AND TO_CHAR(CDATE, 'yyyy-MM-dd') = #{plateDate, jdbcType=VARCHAR} AND HODING_TYPE IN (#{POSITION_TYPE_04}, #{POSITION_TYPE_06}) GROUP BY FINPROD_ID ) pledge ON pledge.FINPROD_ID = pledgeList.pledgeId INNER JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = pledgeList.pledgeId LEFT JOIN MST_BOND_VALUATION_INFO mbvi ON mbvi.SEC_ID = fp.FINPROD_MARKET_ID AND TO_CHAR(mbvi.VALUE_DATE, 'yyyy-MM-dd') <= #{plateDate, jdbcType=VARCHAR} AND NOT EXISTS ( SELECT 1 FROM MST_BOND_VALUATION_INFO mbviInner WHERE mbviInner.SEC_ID = fp.FINPROD_MARKET_ID AND TO_CHAR(mbviInner.VALUE_DATE, 'yyyy-MM-dd') <= #{plateDate, jdbcType=VARCHAR} AND TO_CHAR(mbviInner.VALUE_DATE, 'yyyy-MM-dd') > TO_CHAR(mbvi.VALUE_DATE, 'yyyy-MM-dd') )

SELECT fp.FINPROD_MARKET_ID bondCode, fp.FINPROD_ABBR bondAbbrName, fp.MDATE mdate, '' avaPledgePrin, NVL(pledgeList.PLEDGE_NUMBER, 0) * 100 pledgePrin, mbvi.NETPRICE firstNetPrice, pledgeList.PLEDGE_RATIO*100 pledgeRatio, '' prin, fp.REGIST_ORG repRegistOrg FROM (
SELECT ENTRUST_ID bussId, FINPROD_ID pledgeId, PLEDGE_FACE_VALUE, PLEDGE_NUMBER, PLEDGE_RATIO, PLEDGE_AMT FROM ETR_PLEDGE WHERE ENTRUST_ID = #{entrustId}
SELECT fdp.FINPROD_ID bussId, fdp.PLEDGE_FINPROD_ID pledgeId, fdp.PLEDGE_FACE_VALUE, fdp.PLEDGE_NUMBER, fdp.PLEDGE_RATIO, fdp.PLEDGE_AMT FROM FIN_DEAL_PLEDGE fdp LEFT JOIN TRD_PRODUCT_DEAL tpd ON tpd.TRADE_ID = fdp.FINPROD_ID WHERE (tpd.IS_CANCEL = #{YES_OR_NO_N} AND fdp.FINPROD_ID = #{bizCode}) OR (tpd.IS_CANCEL = #{YES_OR_NO_Y} AND fdp.FINPROD_ID = SUBSTR(#{bizCode}, 0, LENGTH(#{bizCode})-1))
) pledgeList LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_MARKET_ID = SUBSTR(pledgeList.pledgeId, 5) AND fp.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} LEFT JOIN MST_BOND_VALUATION_INFO mbvi ON mbvi.SEC_ID = fp.FINPROD_MARKET_ID AND TO_CHAR(mbvi.VALUE_DATE, 'yyyy-MM-dd') <= #{plateDate, jdbcType=VARCHAR} AND NOT EXISTS ( SELECT 1 FROM MST_BOND_VALUATION_INFO mbviInner WHERE mbviInner.SEC_ID = fp.FINPROD_MARKET_ID AND TO_CHAR(mbviInner.VALUE_DATE, 'yyyy-MM-dd') <= #{plateDate, jdbcType=VARCHAR} AND TO_CHAR(mbviInner.VALUE_DATE, 'yyyy-MM-dd') > TO_CHAR(mbvi.VALUE_DATE, 'yyyy-MM-dd') )
